import{_ as a,o as r,c as s,a2 as t}from"./chunks/framework.D3xAlClj.js";const l="/entislng/v4/assets/a25e99b619258ddc-20261015000315-1p1xpcm.CJB093c9.png",i="/entislng/v4/assets/95fbd3c194dbdd09-20261015000315-0nymyly.cAYTZCQh.png",n="/entislng/v4/assets/5e225ff1e69b673a-20261015000315-kd8hqfo.BCQCkb2j.png",o="/entislng/v4/assets/619e03ebf63cb3c4-20261015000315-9kxec6q.5CwByMlo.png",c="/entislng/v4/assets/104c1ed707690cd3-20261015000315-uklhza5.BlvFboQ1.png",_="/entislng/v4/assets/fdcfbfd73b452452-20261015000315-790ejuz.BSlboOyL.png",p="/entislng/v4/assets/322c89fc08854fa4-20261015000315-2nbfy3n.DhDQtC0j.png",d="/entislng/v4/assets/d1e23c930a0346a8-20261015000315-b8rc292.BGN0aE2F.png",h="/entislng/v4/assets/1046981894061a0e-20261015000315-boynp4k.DhXwBkOx.png",x=JSON.parse('{"title":"SqlServer安装(适用于2008R2,2014,2017)","description":"","frontmatter":{"title":"SqlServer安装(适用于2008R2,2014,2017)","date":"2026-10-14T16:03:15.000Z","lastmod":"2026-11-24T18:17:09.000Z"},"headers":[],"relativePath":"guide/1209.md","filePath":"guide/帮助文档/安装卸载说明/数据库安装卸载说明/SqlServer安装(适用于2008R2,2014,2017).md"}'),m={name:"guide/1209.md"};function q(b,e,g,u,S,f){return r(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="sqlserver安装-适用于2008r2-2014-2017" tabindex="-1">SqlServer安装(适用于2008R2,2014,2017) <a class="header-anchor" href="#sqlserver安装-适用于2008r2-2014-2017" aria-label="Permalink to &quot;SqlServer安装(适用于2008R2,2014,2017)&quot;">​</a></h1><h3 id="_1-双击运行-sql-server-安装包-等待解压缩完成-如图" tabindex="-1">1：双击运行 Sql Server 安装包，等待解压缩完成，如图： <a class="header-anchor" href="#_1-双击运行-sql-server-安装包-等待解压缩完成-如图" aria-label="Permalink to &quot;1：双击运行 Sql Server 安装包，等待解压缩完成，如图：&quot;">​</a></h3><p><img src="'+l+'" alt=""></p><h3 id="_2-解压缩完成后-显示安装界面" tabindex="-1">2：解压缩完成后，显示安装界面 <a class="header-anchor" href="#_2-解压缩完成后-显示安装界面" aria-label="Permalink to &quot;2：解压缩完成后，显示安装界面&quot;">​</a></h3><p><img src="'+i+'" alt=""></p><h3 id="_3-用户协议确认-选择接受此协议-然后点击下一步" tabindex="-1">3：用户协议确认，选择接受此协议，然后点击下一步 <a class="header-anchor" href="#_3-用户协议确认-选择接受此协议-然后点击下一步" aria-label="Permalink to &quot;3：用户协议确认，选择接受此协议，然后点击下一步&quot;">​</a></h3><p><img src="'+n+'" alt=""></p><h3 id="_4-选择安装模块-建议全部选中-然后点击下一步继续" tabindex="-1">4：选择安装模块，建议全部选中，然后点击下一步继续 <a class="header-anchor" href="#_4-选择安装模块-建议全部选中-然后点击下一步继续" aria-label="Permalink to &quot;4：选择安装模块，建议全部选中，然后点击下一步继续&quot;">​</a></h3><p><img src="'+o+'" alt=""></p><h3 id="_5-进入安装实例配置界面-建议保持默认-sqlexpress-不用修改-然后点击下一步-继续" tabindex="-1">5：进入安装实例配置界面，建议保持默认（SqlExpress），不用修改，然后点击下一步，继续 <a class="header-anchor" href="#_5-进入安装实例配置界面-建议保持默认-sqlexpress-不用修改-然后点击下一步-继续" aria-label="Permalink to &quot;5：进入安装实例配置界面，建议保持默认（SqlExpress），不用修改，然后点击下一步，继续&quot;">​</a></h3><p><img src="'+c+'" alt=""></p><h3 id="_6-进入服务角色配置界面" tabindex="-1">6：进入服务角色配置界面 <a class="header-anchor" href="#_6-进入服务角色配置界面" aria-label="Permalink to &quot;6：进入服务角色配置界面&quot;">​</a></h3><p>此处如已默认选择，则保持默认即可；如果没有默认选择，请按如下选择：</p><ul><li>Sql Server Database Engine：选择 Network Service，启动类型选自动。</li><li>Sql Server Browser：选择 Local Service；如果本机数据要对外开放，则启动类型选自动，否则选禁用。</li></ul><p><img src="'+_+'" alt=""></p><h3 id="_7-进入服务器认证方式配置" tabindex="-1">7：进入服务器认证方式配置 <a class="header-anchor" href="#_7-进入服务器认证方式配置" aria-label="Permalink to &quot;7：进入服务器认证方式配置&quot;">​</a></h3><p>如果数据库要对外开放，请选择混合认证（建议）；如果确认数据库不对外开放，也可以保持默认。其他几项都保持默认即可。</p><p><img src="'+p+'" alt=""></p><h3 id="_8-后面几步保持默认-直到安装开始" tabindex="-1">8：后面几步保持默认，直到安装开始 <a class="header-anchor" href="#_8-后面几步保持默认-直到安装开始" aria-label="Permalink to &quot;8：后面几步保持默认，直到安装开始&quot;">​</a></h3><p>安装时间稍长，请耐心等待，正常情况下一般在 5 分钟左右即可完成安装。</p><p><img src="'+d+'" alt=""></p><h3 id="_9-安装完成" tabindex="-1">9：安装完成 <a class="header-anchor" href="#_9-安装完成" aria-label="Permalink to &quot;9：安装完成&quot;">​</a></h3><p><img src="'+h+'" alt=""></p>',23)])])}const k=a(m,[["render",q]]);export{x as __pageData,k as default};
